import sys

def encode(arr, length):
    val = 0
    for i in range(length):
        val = val * 3 + arr[i]
    return val

def decode(arr, length, code, base):
    for j in range(length - 1, -1, -1):
        arr[j] = code % base
        code //= base

def run_program():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    if n < m:
        n, m = m, n
    totalStates = 1
    for _ in range(m):
        totalStates *= 3
    dp = [-1] * totalStates
    tempDp = [-1] * totalStates
    arrA = [1] * m
    arrB = [0] * m
    dp[encode(arrA, m)] = 0
    index_input = 2
    for _ in range(n):
        for i in range(totalStates):
            tempDp[i] = -1
        for index in range(totalStates):
            if dp[index] < 0:
                continue
            decode(arrA, m, index, 3)
            for mask in range(1 << m):
                for j in range(m):
                    arrB[j] = (mask >> j) & 1
                invalid = False
                for j in range(m):
                    if arrA[j] == 0 and arrB[j] == 0:
                        invalid = True
                        break
                if invalid:
                    continue
                countOnes = 0
                for j in range(m):
                    if arrB[j] == 1:
                        arrB[j] = 2
                        countOnes += 1
                for j in range(m):
                    if arrB[j] == 0 and (arrA[j] == 2 or (j > 0 and arrB[j - 1] == 2) or (j + 1 < m and arrB[j + 1] == 2)):
                        arrB[j] = 1
                newIdx = encode(arrB, m)
                tempDp[newIdx] = max(tempDp[newIdx], dp[index] + m - countOnes)
        dp, tempDp = tempDp, dp
    maxVal = 0
    for idx in range(totalStates):
        if dp[idx] <= maxVal:
            continue
        decode(arrA, m, idx, 3)
        bad = False
        for j in range(m):
            if arrA[j] == 0:
                bad = True
                break
        if not bad:
            maxVal = dp[idx]
    print(maxVal)

